@test "caminho feliz produz arquivo higienizado e JSONL valido" {
  run "${SCRIPT}" "${FIXTURES}/sample-raw.jsonl" "${REF}"
  [ "${status}" -eq 0 ]
  [ -f "${OUT}" ]
  run jq empty "${OUT}"
  [ "${status}" -eq 0 ]
}

main() {
  local build_flag=""
  case "${1:-}" in
    --build) build_flag="--build" ;;
    "")      ;;
    *)       die "Argumento desconhecido: '$1' (use --build ou nenhum)." ;;
  esac

  detect_compose
  ensure_env
  warn_busy_app_ports

auth() {
  # Conexao TCP a 127.0.0.1 dentro do conteiner: passa pelo pg_hba scram, validando a senha.
  dc exec -e PGPASSWORD="$1" -T db \
    psql -h 127.0.0.1 -U leadscorer -d leadscorer -c 'select 1' >/dev/null 2>&1
}
